    const tags = (id) => Object.keys(ROLE).filter((k) => R[k] === id).map((k) => `<span class="lu-tag${k === 'captain' ? ' cap' : ''}">${ROLE[k][0]}</span>`).join('');
    const out = players().filter((p) => statusOf(p) !== 'Fit');
