  A.CH.gup = (el) => { const f = el.files[0]; if (!f) return; const r = new FileReader(); r.onload = () => { S.gUp = r.result; S.gUpName = f.name; A.render(); DU.toast('Your design is ready to download or post'); }; r.readAsDataURL(f); };
