    const vb = svg.match(/viewBox="0 0 (\d+) (\d+)"/); const w = Number(vb[1]), h = Number(vb[2]);
    const img = new Image(); img.onload = () => { const c = document.createElement('canvas'); c.width = w; c.height = h; c.getContext('2d').drawImage(img, 0, 0, w, h); c.toBlob((b) => { const a = document.createElement('a'); a.href = URL.createObjectURL(b); a.download = `dallas-united-${S.gk || 'xi'}-${S.gz || 'sq'}.png`; a.click(); DU.toast('Graphic downloaded'); }); };
