    const sel = S.calSel && (all.find((e) => e.key === S.calSel) || (d.calEvents || []).map((e) => ({ ...e, key: `custom|${e.id}`, src: 'custom', ref: e.id })).find((e) => e.key === S.calSel));
    const cfg = calCfg();
