      <div class="chips">${Object.keys(CT).map((k) => `<button type="button" class="chip" aria-pressed="${shown.includes(k)}" data-act="calt" data-k="${k}"><span style="display:inline-block;width:10px;height:10px;border-radius:50%;background:${CT[k][0]};margin-right:6px"></span>${k}</button>`).join('')}</div>
