  A.ACT.calsave = (el) => { const g = (k) => DU.$(`[data-cale="${k}"]`).value.trim(); if (!g('date') || !g('t')) { DU.toast('Pick a date and say what it is.'); return; } const tm = g('time'); A.commit(`Calendar: changed “${g('t')}”`, (d) => { const e = (d.calEvents || []).find((x) => x.id === el.dataset.k); if (e) Object.assign(e, { date: g('date'), time: tm, type: g('type'), title: g('t'), t: `${tm ? `${DU.fmtTime(tm)} ` : ''}${g('t')}` }); }); S.calSel = null; A.render(); DU.toast('Event saved'); };
